/* zanac_stubs.h - bookkeeping for the not-yet-ported procedures.
 *
 * stubs.c is regenerated by c_src/tools/gen_support.py on every build; it
 * contains one placeholder per procedure that has no ported definition yet.
 * The placeholders record their calls, so zanac_stub_report() prints exactly
 * which parts of the game are still missing (and how often they were reached).
 */
#ifndef ZANAC_STUBS_H
#define ZANAC_STUBS_H

#include <stdint.h>

/* Called by a placeholder. */
void zanac_stub_hit(const char *name, uint16_t addr);

/* Number of distinct procedures still stubbed. */
int zanac_stub_count(void);

/* Print every stubbed procedure that was reached, with its call count. */
void zanac_stub_report(void);

#endif /* ZANAC_STUBS_H */
